(function(){"use strict";var selects=[].slice.call(document.querySelectorAll("select[data-pr-route]"));if(!selects.length)return;function radios(name){return[].slice.call(document.querySelectorAll('input[type="radio"][name="'+name+'"]'))}function toRadios(select){var name=select.getAttribute("data-pr-route");radios(name).forEach(function(r){var on=r.value===select.value;if(r.checked!==on){r.checked=on;if(on){if(window.jQuery)window.jQuery(r).trigger("change");else r.dispatchEvent(new Event("change",{bubbles:true}))}}})}function toSelect(select){var name=select.getAttribute("data-pr-route");var checked=document.querySelector('input[type="radio"][name="'+name+'"]:checked');if(checked&&select.value!==checked.value)select.value=checked.value}selects.forEach(function(select){toRadios(select);select.addEventListener("change",function(){toRadios(select)});radios(select.getAttribute("data-pr-route")).forEach(function(r){r.addEventListener("change",function(){toSelect(select)})})});var form=selects[0].form;if(form){form.addEventListener("reset",function(){setTimeout(function(){selects.forEach(toSelect)},0)})}})();